import{_ as t,c as a,o as i,ag as r}from"./chunks/framework.DzTbpWAc.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),n={name:"guide/index.md"};function o(s,e,l,d,c,u){return i(),a("div",null,e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><code>reactive-proxy-state</code> is a lightweight reactivity system inspired by Vue 3&#39;s reactivity API but designed to be used standalone in any JavaScript or TypeScript environment, whether it&#39;s browser, Node.js, or any other JavaScript runtime.</p><h2 id="what-is-reactivity" tabindex="-1">What is Reactivity? <a class="header-anchor" href="#what-is-reactivity" aria-label="Permalink to &quot;What is Reactivity?&quot;">​</a></h2><p>Reactivity is a programming paradigm that allows us to automatically track dependencies between data and the code that uses that data. When the data changes, the dependent code re-executes automatically.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Simple API</strong>: Familiar if you&#39;ve used Vue 3, easy to learn if you haven&#39;t</li><li><strong>Lightweight</strong>: Focused on the core reactivity system with minimal bloat</li><li><strong>Framework-agnostic</strong>: Use in any JavaScript environment</li><li><strong>TypeScript support</strong>: Full type definitions included</li><li><strong>Collection support</strong>: Works with Arrays, Maps, Sets</li><li><strong>Zero dependencies</strong>: Standalone package with no external dependencies</li></ul><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><ul><li>Building real-time state synchronization systems</li><li>Creating custom state management solutions</li><li>Server-side reactive data processing</li><li>Anywhere you need automated dependency tracking and effect triggering</li></ul><p>This library is particularly well-suited for scenarios where you need reactivity outside of a UI framework, or when you want to build custom state management with a reactive core.</p>',9)]))}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
